using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
namespace PZ3D {
 sealed class PresentationBridge {
  public const string Id="OrangeShootPresentation",Name="OrangeShootPresentation.jar",ConfigName="OrangeShootPresentation.properties";
  public string LastBackup;
  static readonly JavaScriptSerializer json=new JavaScriptSerializer();
  static string Hash(byte[] b){using(var s=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(s.ComputeHash(b)).Replace("-","");}
  static byte[] Asset(){return BundledAssets.ReadOwnAsset(Name);}
  string Journal(Engine e){return Path.Combine(e.Data,"shoot-presentation-"+Hash(Encoding.UTF8.GetBytes(e.Game.ToUpperInvariant()))+".json");}
  static string Folder(Engine e){return Path.Combine(Path.GetDirectoryName(e.Mods),Id);}
  public static string PropertiesPath(Engine e){return Path.Combine(Folder(e),"42","media","java","client",ConfigName);}
  static string Jar(Engine e){return Path.Combine(Path.GetDirectoryName(PropertiesPath(e)),Name);}
  static string Info(Engine e){return Path.Combine(Folder(e),"42","mod.info");}
  static string[] Args(Dictionary<string,object> cfg){return ((System.Collections.IEnumerable)cfg["vmArgs"]).Cast<object>().Select(Convert.ToString).ToArray();}
  static bool Has(string text){return Regex.IsMatch(text,@"(?m)^\s*mod\s*=\s*OrangeShootPresentation\s*,");}
  bool IsAddon(Engine e){try{return File.Exists(Journal(e))&&json.Deserialize<Dictionary<string,string>>(File.ReadAllText(Journal(e))).ContainsKey("addon");}catch{return false;}}
  public bool Enabled(Engine e){if(!IsAddon(e)||!File.Exists(Jar(e))||!File.Exists(Info(e))||!File.Exists(PropertiesPath(e))||!File.Exists(e.Mods)||!Has(File.ReadAllText(e.Mods)))return false;string info=File.ReadAllText(Info(e));return Regex.IsMatch(info,@"(?m)^id=OrangeShootPresentation\s*$")&&Regex.IsMatch(info,@"(?m)^javaPkgName=orange\.ads\s*$")&&Regex.IsMatch(info,@"(?m)^javaJarFile=media/java/client/OrangeShootPresentation\.jar\s*$");}
  public string RepairStartup(Engine e){e.Guard();if(!IsAddon(e)&&File.ReadAllText(e.Config).Contains("-javaagent:"+Name)){RetireLegacy(e);return "已备份撤销旧开镜javaagent启动项，保留基础3D、枪械及汉化选择。\r\n备份："+LastBackup;}return "启动配置无旧开镜javaagent，未改其他参数。";}
  void RetireLegacy(Engine e){if(!IsAddon(e)){var legacy=new LegacyPresentationBridge();string p=Journal(e);if(File.Exists(p)||File.ReadAllText(e.Config).Contains("-javaagent:"+Name)){legacy.Disable(e);LastBackup=legacy.LastBackup;}else if(File.Exists(Path.Combine(e.Game,Name))||File.Exists(Path.Combine(e.Game,ConfigName)))throw new Exception("发现未记录的旧开镜文件，请先核对人工恢复说明；不覆盖未知文件。");}}
  public string Enable(Engine e,string source){e.Guard();if(!ShootClient.BaseReady(e)||!ShootClient.Enabled(e))throw new Exception("请先安装基础3D和枪械扩展。");ShootClient.Validate(source);string author=Path.Combine(source,"mods",ShootClient.Id,"42","media","java","client","ISeeThem.jar");byte[] asset=Asset();string text=ReticleSettings.Load(e.Data).Properties(author)+"shoot.sha256="+Hash(File.ReadAllBytes(author))+"\n";RetireLegacy(e);VerifyApi(e,author,asset);if(!IsAddon(e)&&(File.Exists(Jar(e))||File.Exists(PropertiesPath(e))||File.Exists(Info(e))))throw new Exception("存在未记录的同名本地补丁，拒绝覆盖。");string info="name=Orange local aim fallback\nid="+Id+"\nversionMin=42.21\nrequire=\\ZombieBuddy,\\Viewpoint\nZBVersionMin=2.3.0\njavaJarFile=media/java/client/"+Name+"\njavaPkgName=orange.ads\nloadModAfter=Viewpoint,ShootToThrillMultiplayer\n";
   if(Enabled(e)&&File.ReadAllBytes(Jar(e)).SequenceEqual(asset)&&File.ReadAllText(PropertiesPath(e))==text&&File.ReadAllText(Info(e))==info)return "本地瞄准补丁已是当前配置；通过Buddy加载，没有额外javaagent。";
   return Commit(e,new Dictionary<string,byte[]>{{Jar(e),asset},{PropertiesPath(e),Encoding.UTF8.GetBytes(text)},{Info(e),Encoding.UTF8.GetBytes(info)}},true)+"\r\n枪械接口检查通过（非画面兼容保证）；首次需批准 orange.ads / "+Name+"。无需额外Java启动插件。";
  }
  public string Disable(Engine e){e.Guard();if(!IsAddon(e)){var legacy=new LegacyPresentationBridge();string result=legacy.Disable(e);LastBackup=legacy.LastBackup;return result;}return Commit(e,new Dictionary<string,byte[]>{{Jar(e),null},{PropertiesPath(e),null},{Info(e),null}},false);}
  static string BackupLabel(int index,string path){string name=Path.GetFileName(path);if(name.Length>60)name=Path.GetFileNameWithoutExtension(path).Substring(0,20)+"-"+Hash(Encoding.UTF8.GetBytes(path)).Substring(0,12)+Path.GetExtension(path);return index+"-"+name;}
  string Commit(Engine e,Dictionary<string,byte[]> files,bool on){byte[] mods=File.ReadAllBytes(e.Mods),launch=File.ReadAllBytes(e.Config);string text=Encoding.UTF8.GetString(mods).TrimStart('\uFEFF');var block=Regex.Match(text,@"\bmods\s*\{(?<body>[^}]*)\}");if(!block.Success)throw new Exception("模组列表格式不识别，未修改。");string body=Regex.Replace(block.Groups["body"].Value,@"(?m)^[ \t]*mod\s*=\s*OrangeShootPresentation\s*,[^\r\n]*(?:\r?\n|$)","");if(on)body=body.TrimEnd()+"\r\n    mod = OrangeShootPresentation,\r\n";text=text.Substring(0,block.Groups["body"].Index)+body+text.Substring(block.Groups["body"].Index+block.Groups["body"].Length);var cfg=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(launch).TrimStart('\uFEFF'));if(Args(cfg).Any(a=>a.StartsWith("-javaagent:",StringComparison.OrdinalIgnoreCase)&&a.Contains(Name)))throw new Exception("仍有旧插件启动参数，请先按旧备份撤销，未部署新插件。");files[e.Mods]=Encoding.UTF8.GetBytes(text);files[e.Config]=launch;
   string journal=Journal(e),backup=Path.Combine(e.Data,"shoot-backups","buddy-addon-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(backup);LastBackup=backup;var originals=new Dictionary<string,byte[]>();foreach(string path in files.Keys.Concat(new[]{journal})){originals[path]=File.Exists(path)?File.ReadAllBytes(path):null;if(originals[path]!=null)File.WriteAllBytes(Path.Combine(backup,BackupLabel(originals.Count,path)),originals[path]);if(File.Exists(path))using(var lockFile=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){} }
   File.WriteAllText(Path.Combine(backup,"人工恢复开镜桥接.txt"),"此版本通过Buddy加载本地mods/OrangeShootPresentation，不增加Java启动项。退出游戏后从 "+e.Mods+" 仅移除 mod = OrangeShootPresentation, 可停用。不要删除其他模组或JavaDLL。\r\n本次文件与备份序号：\r\n"+string.Join("\r\n",originals.Select((p,i)=>BackupLabel(i+1,p.Key)+" => "+p.Key)),new UTF8Encoding(true));
   try{if(!File.ReadAllBytes(e.Mods).SequenceEqual(mods)||!File.ReadAllBytes(e.Config).SequenceEqual(launch))throw new Exception("配置被外部修改，拒绝覆盖。");e.Guard();foreach(var file in files){if(file.Value==null){if(File.Exists(file.Key))File.Delete(file.Key);}else if(file.Key!=e.Config){Directory.CreateDirectory(Path.GetDirectoryName(file.Key));Atomic(file.Key,file.Value);}}if(on)Atomic(journal,Encoding.UTF8.GetBytes(json.Serialize(new Dictionary<string,string>{{"addon","2"},{"jarHash",Hash(files[Jar(e)])},{"propertiesHash",Hash(files[PropertiesPath(e)])},{"backup",backup}})));else File.Delete(journal);}
   catch(Exception error){var failures=new List<string>();foreach(var old in originals)try{if(old.Value==null){if(File.Exists(old.Key))File.Delete(old.Key);}else{Directory.CreateDirectory(Path.GetDirectoryName(old.Key));Atomic(old.Key,old.Value);}}catch(Exception ex){failures.Add(old.Key+": "+ex.Message);}throw new Exception(error.Message+"\r\n"+(failures.Count==0?"本阶段已回滚；旧启动插件的迁移停用不自动恢复。":"部分回滚失败："+string.Join("; ",failures))+"\r\n备份："+backup,error);}
   return (on?"本地瞄准补丁已配置，由Buddy加载；进服效果待验证。":"本地瞄准补丁已卸载，保留枪械、3D及其他配置。")+"\r\n备份："+backup;
  }
  static void Atomic(string path,byte[] bytes){string temp=path+".orange-"+Guid.NewGuid().ToString("N");try{File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  static void VerifyApi(Engine e,string author,byte[] asset){if(e.TestMode)return;string java=Path.Combine(e.Game,"jre64","bin","java.exe");if(!File.Exists(java))throw new Exception("游戏自带Java不存在，未启用瞄准补丁。");string dir=Path.Combine(e.Data,"compat-probe",Hash(asset));Directory.CreateDirectory(dir);string helper=Path.Combine(dir,Name);File.WriteAllBytes(helper,asset);string view=Path.Combine(e.ViewSource??Path.Combine(e.Workshop,"3809306528"),"mods","Viewpoint","42","media","java","client","Viewpoint.jar");string cp=string.Join(";",new[]{helper,author,view,Path.Combine(e.Game,"projectzomboid.jar"),e.Game,Path.Combine(e.Game,"ZombieBuddy.jar")});var psi=new ProcessStartInfo(java,"-Xms16m -Xmx128m -cp \""+cp+"\" orange.ads.Preflight \""+author+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(psi)){var output=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(20000)){process.Kill();throw new Exception("接口检查超时；枪械本体可保留，汉化继续安装。");}System.Threading.Tasks.Task.WaitAll(output,errors);if(process.ExitCode!=0)throw new Exception("当前枪械/游戏接口不兼容本地瞄准补丁，不影响汉化。\r\n"+output.Result+errors.Result);}}
 }
}
